INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(92510265, 'Black Luster Soldier - Sacred Soldier', '圣战士 混沌战士', '聖戦士カオス・ソルジャー', 'Effect Monster', 'Warrior', 'LIGHT', 8, 3000, 2500, '「圣战士 混沌战士」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时，以除外的1只自己的光属性或者暗属性的怪兽和对方场上1张卡为对象才能发动。那张自己的卡回到墓地，那张对方的卡除外。 ②：这张卡战斗破坏对方怪兽时，以自己墓地1只7星以下的战士族怪兽为对象才能发动。那只怪兽加入手卡。'),
(49202162, 'Black Luster Soldier - Soldier of Chaos', '混元的战士 混沌士兵', '混沌の戦士 カオス・ソルジャー', 'Link Monster', 'Warrior', 'EARTH', NULL, 3000, NULL, '卡名不同的怪兽3只 ①：这张卡是已用7星以上的怪兽为素材作连接召唤的场合，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：这张卡战斗破坏对方怪兽时，可以从以下效果选择1个发动。 ●这张卡的攻击力上升1500。 ●这张卡在下次的自己回合的战斗阶段中可以作2次攻击。 ●场上1张卡除外。'),
(54484652, 'Black Luster Soldier - Super Soldier', '超战士 混沌士兵', '超戦士カオス・ソルジャー', 'Ritual Effect Monster', 'Warrior', 'EARTH', 8, 3000, 2500, '「超战士的仪式」降临。自己对「超战士 混沌战士」1回合只能有1次特殊召唤。 ①：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「暗黑骑士 盖亚」怪兽特殊召唤。'),
(76792184, 'Black Magic Ritual', '混沌－黑魔术仪式', 'カオス－黒魔術の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「黑混沌之魔术师」的降临必需。必须从自己的手卡·场上把等级合计直到8以上的怪兽解放。'),
(86469231, 'Black Mamba', '黑曼巴', 'ブラックマンバ', 'Effect Monster', 'Reptile', 'DARK', 3, 1300, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有爬虫类族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。从卡组把1只爬虫类族怪兽送去墓地，作为对象的怪兽的表示形式变更。'),
(93969023, 'Black Metal Dragon', '黑钢龙', '黒鋼竜', 'Effect Monster', 'Dragon', 'DARK', 1, 600, 600, '①：以自己场上1只「真红眼」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升600的装备魔法卡使用给那只自己怪兽装备。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把1张「真红眼」卡加入手卡。'),
(65169794, 'Black Pendant', '黑项链', '黒いペンダント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升500。 ②：这张卡从场上送去墓地的场合发动。给与对方500伤害。'),
(76218643, 'Black Potan', '黑面波波', 'ブラックポータン', 'Effect Monster', 'Fiend', 'DARK', 1, 200, 100, '自己场上有调整表侧表示存在的场合，这张卡不会被战斗破坏。自己场上表侧表示存在的调整从场上离开时，自己回复800基本分。'),
(90654356, 'Black Ptera', '暗黑翼龙', '暗黒プテラ', 'Effect Monster', 'Dinosaur', 'WIND', 3, 1000, 500, '这张卡被战斗破坏以外的方法从场上送去墓地时，这张卡回到持有者手卡。'),
(74416224, 'Black Ray Lancer', '黑鳍条枪兵', 'ブラック・レイ・ランサー', 'XYZ Monster', 'Beast-Warrior', 'DARK', 3, 2100, 600, '水属性3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择场上表侧表示存在的1只怪兽才能发动。选择的怪兽的效果直到结束阶段时无效。'),
(72278479, 'Black Return', '黑翼返回', 'ブラック・リターン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '名字带有「黑羽」的怪兽1只特殊召唤成功时，选择对方场上表侧表示存在的1只怪兽发动。自己基本分回复选择的对方怪兽的攻击力的数值，那只怪兽回到持有者手卡。'),
(73580471, 'Black Rose Dragon', '黑蔷薇龙', 'ブラック・ローズ・ドラゴン', 'Synchro Monster', 'Dragon', 'FIRE', 7, 2400, 1800, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤时才能发动。场上的卡全部破坏。 ②：1回合1次，从自己墓地把1只植物族怪兽除外，以对方场上1只守备表示怪兽为对象才能发动。那只对方的守备表示怪兽变成表侧攻击表示，那个攻击力直到回合结束时变成0。'),
(69053263, 'Black Rose Garden', '黑蔷薇华园', '黒薔薇の華園', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从自己的卡组·墓地把1只「蔷薇龙」怪兽加入手卡。 ②：场上的表侧表示怪兽变成植物族。 ③：这张卡被破坏的场合发动。给与对方为自己的墓地·除外状态的植物族怪兽数量×100伤害。被「黑蔷薇龙」的效果破坏的场合，再给与对方2400伤害。'),
(33698022, 'Black Rose Moonlight Dragon', '月华龙 黑蔷薇', '月華竜 ブラック・ローズ', 'Synchro Monster', 'Dragon', 'LIGHT', 7, 2400, 1800, '调整＋调整以外的怪兽1只以上 这张卡特殊召唤成功时或者对方场上有5星以上的怪兽特殊召唤时发动。选择对方场上1只特殊召唤的怪兽回到持有者手卡。「月华龙 黑蔷薇」的效果1回合只能使用1次。'),
(88671720, 'Black Salvo', '黑色炸弹球', 'ブラック・ボンバー', 'Tuner Monster', 'Machine', 'DARK', 3, 100, 1100, '这张卡召唤成功时，可以把自己墓地存在的1只机械族·暗属性的4星怪兽表侧守备表示特殊召唤。这个效果特殊召唤的效果怪兽的效果无效化。'),
(96367119, 'Black Shadow Squall', '疾黑崇高', 'ブラック・ノーブル', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：魔法·陷阱卡发动时，把自己场上1个黑羽指示物取除才能发动。那个发动无效并破坏。 ②：自己场上有「黑翼龙」存在的场合才能发动。墓地的这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(67284108, 'Black Sheep Token', '替罪鬼羊', 'スケープ・ゴースト', 'Token', 'Zombie', NULL, NULL, NULL, NULL, NULL),
(11901678, 'Black Skull Dragon', '黑恶魔龙', 'ブラック・デーモンズ・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 9, 3200, 2500, '「恶魔召唤」＋「真红眼黑龙」'),
(72930878, 'Black Sonic', '黑翼音速', 'ブラック・ソニック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽只有「黑羽」怪兽3只的场合，这张卡的发动从手卡也能用。 ①：对方怪兽向自己场上的「黑羽」怪兽攻击宣言时才能发动。对方场上的表侧攻击表示怪兽全部除外。'),
(79409334, 'Black Stego', '暗黑剑龙', '暗黒ステゴ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1200, 2000, '这张卡被选择作为对方怪兽的攻击对象时，这张卡变成守备表示。'),
(52833089, 'Black Thunder', '黑翼雷电', 'ブラック・サンダー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「黑羽」的怪兽被战斗破坏送去墓地时才能发动。对方场上存在的卡每有1张，给与对方基本分400分伤害。'),
(38670435, 'Black Tyranno', '暗黑恐兽', '暗黒恐獣', 'Effect Monster', 'Dinosaur', 'EARTH', 7, 2600, 1800, '当对方场上仅有守备表示的怪兽存在时，这张卡可以对对方进行直接攻击。'),
(52319752, 'Black Veloci', '暗黑迅猛龙', '暗黒ヴェロキ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1800, 300, '这张卡向对方怪兽攻击的场合，伤害步骤内攻击力上升400。这张卡被对方怪兽攻击的场合，伤害步骤内攻击力下降400。'),
(91351370, 'Black Whirlwind', '黑旋风', '黒い旋風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上有「黑羽」怪兽召唤时才能发动。把持有比那只怪兽低的攻击力的1只「黑羽」怪兽从卡组加入手卡。'),
(9925982, 'Black Wing Revenge', '黑翼复仇', 'ブラック・リベンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的鸟兽族怪兽被战斗破坏送去墓地时才能发动。在自己场上把2只「黑羽-黑冠衍生物」（鸟兽族·暗·2星·攻0/守800）特殊召唤。'),
(73218989, 'Black-Winged Assault Dragon', '黑翼强袭龙', 'ブラックフェザー・アサルト・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 10, 3200, 2800, '同调怪兽调整＋调整以外的怪兽1只以上 这张卡用同调召唤以及以下方法才能特殊召唤。 ●从自己的场上（表侧表示）·墓地把同调怪兽调整1只和「黑翼龙」1只除外的场合可以从额外卡组特殊召唤。 ①：每次对方把怪兽的效果发动，给这张卡放置1个黑羽指示物，给与对方700伤害。 ②：对方回合，把有黑羽指示物4个以上放置的这张卡解放才能发动。场上的卡全部破坏。'),
(9012916, 'Black-Winged Dragon', '黑翼龙', 'ブラックフェザー・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 2800, 1600, '调整＋调整以外的怪兽1只以上 ①：自己受到效果伤害的场合，作为代替给这张卡放置1个黑羽指示物。 ②：这张卡的攻击力下降这张卡的黑羽指示物数量×700。 ③：1回合1次，把这张卡的黑羽指示物全部取除，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力下降取除的黑羽指示物数量×700，给与对方下降数值的伤害。'),
(67779172, 'Black-Winged Strafe', '黑翼射击', 'ブラックフェザー・シュート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「黑羽」的怪兽送去墓地，选择对方场上守备表示存在的1只怪兽发动。选择的怪兽送去墓地。'),
(44028461, 'Blackback', '黑翼回归', 'ブラック・バック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己回合才能发动。选择自己墓地存在的1只攻击力2000以下的名字带有「黑羽」的怪兽特殊召唤。这张卡发动的回合，自己不能把怪兽通常召唤。'),
(67647362, 'Blackbeard, the Plunder Patroll Captain', '海造贼-黑胡子船长', '海造賊－キャプテン黒髭', 'Link Monster', 'Fiend', 'WATER', NULL, 1600, NULL, '包含「海造贼」怪兽的怪兽2只 这个卡名的效果1回合只能使用1次。 ①：以自己场上1只效果怪兽为对象才能发动。把持有和对方的场上·墓地的怪兽的其中任意种相同属性的1只「海造贼」怪兽从额外卡组特殊召唤，作为对象的自己的效果怪兽当作装备卡使用给那只特殊召唤的怪兽装备。那之后，自己从卡组抽1张。这个效果在对方回合也能发动。'),
(80254726, 'Blackbird Close', '黑鸟闭幕', 'ブラック・バード・クローズ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有「黑羽」同调怪兽或者「黑翼龙」存在的场合，这张卡的发动从手卡也能用。 ①：对方场上的怪兽把效果发动时，把自己场上1只表侧表示的「黑羽」怪兽送去墓地才能发动。那个发动无效并破坏。那之后，可以从额外卡组把1只「黑翼龙」特殊召唤。'),
(53519297, 'Blackboost', '黑翼推进', 'ブラック・ブースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的2只名字带有「黑羽」的调整从游戏中除外发动。从自己卡组抽2张卡。'),
(91642007, 'Blackeyes, the Plunder Patroll Seaguide', '海造贼-黑翼水先人', '海造賊－黒翼の水先人', 'Effect Monster', 'Fiend', 'WATER', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：以「海造贼-黑翼水先人」以外的自己墓地1只「海造贼」怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽加入手卡。这个回合，自己不是「海造贼」怪兽不能特殊召唤。 ②：这张卡从手卡·怪兽区域送去墓地的场合，以自己的魔法与陷阱区域1张「海造贼」怪兽卡为对象才能发动。那张卡守备表示特殊召唤。'),
(60992105, 'Blackfeather Darkrage Dragon', '玄翼龙 黑翅', '玄翼竜 ブラック・フェザー', 'Synchro Monster', 'Dragon', 'DARK', 8, 2800, 1600, '调整＋调整以外的怪兽1只以上 1回合1次，战斗或者卡的效果让自己受到伤害时才能发动。从自己卡组上面把最多5张卡送去墓地。这个效果送去墓地的卡之中有怪兽卡的场合，这张卡的攻击力上升400。'),
(87564352, 'Blackland Fire Dragon', '暗黑龙王', '暗黒の竜王', 'Normal Monster', 'Dragon', 'DARK', 4, 1500, 800, '黑暗深处栖息的龙。双眼不太好使。'),
(31053337, 'Blackwing - Abrolhos the Megaquake', '黑羽-激震之亚伯落贺罗斯', 'BF－激震のアブロオロス', 'Effect Monster', 'Winged Beast', 'DARK', 7, 2600, 1800, '这张卡不能特殊召唤。1回合1次，可以把这张卡的攻击力下降1000，对方的魔法与陷阱卡区域存在的卡全部回到持有者手卡。这个效果在主要阶段1才能使用。和这张卡进行战斗的怪兽不会被那次战斗破坏并在伤害计算后回到持有者手卡。'),
(4068622, 'Blackwing - Aurora the Northern Lights', '黑羽-极光之奥罗拉', 'BF－極光のアウロラ', 'Effect Monster', 'Winged Beast', 'LIGHT', 10, -1, NULL, '这张卡不能通常召唤。把自己场上表侧表示存在的1只名字带有「黑羽」的调整和1只调整以外的怪兽从游戏中除外的场合才能特殊召唤。1回合1次，可以从自己的额外卡组把1只名字带有「黑羽」的同调怪兽从游戏中除外，直到结束阶段时当作和那只怪兽同名卡使用，得到相同的攻击力和效果。'),
(17465972, 'Blackwing - Auster the South Wind', '黑羽－南风之奥斯特', 'BF－南風のアウステル', 'Tuner Monster', 'Winged Beast', 'DARK', 4, 1300, NULL, '这张卡不能特殊召唤。 ①：这张卡召唤成功时，以除外的1只自己的4星以下的「黑羽」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：可以把墓地的这张卡除外，从以下效果选择1个发动。 ●选自己场上1只「黑翼龙」放置对方场上的卡数量的黑羽指示物。 ●给对方场上的表侧表示怪兽全部尽可能各放置1个楔指示物（最多1个）。'),
(89040386, 'Blackwing - Backlash', '黑羽-反闪', 'BF－バックフラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地有名字带有「黑羽」的怪兽5只以上存在的场合，对方怪兽的直接攻击宣言时才能发动。对方场上存在的怪兽全部破坏。'),
(9925983, 'Blackwing - Black Crest Token', '黑翼复仇', 'ブラック・リベンジ', 'Token', 'Winged Beast', NULL, NULL, NULL, NULL, NULL),
(22835145, 'Blackwing - Blizzard the Far North', '黑羽－极北之暴冽扎德', 'BF－極北のブリザード', 'Tuner Monster', 'Winged Beast', 'DARK', 2, 1300, NULL, '这张卡不能特殊召唤。 ①：这张卡召唤成功时，以自己墓地1只4星以下的「黑羽」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(25435080, 'Blackwing - Bombardment', '黑羽-力锚', 'BF－アンカー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把1只名字带有「黑羽」的怪兽解放，选择自己场上表侧表示存在的1只同调怪兽发动。选择的怪兽的攻击力直到结束阶段时上升为把这张卡发动而解放的怪兽的攻击力数值。'),
(43906884, 'Blackwing - Boobytrap', '黑羽-地雷', 'BF－マイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的这张卡被对方的效果破坏时，自己场上有名字带有「黑羽」的怪兽表侧表示存在的场合，给与对方基本分1000分伤害，自己从卡组抽1张卡。'),
(49003716, 'Blackwing - Bora the Spear', '黑羽－黑枪之爆流斯特', 'BF－黒槍のブラスト', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1700, 800, '①：自己场上有「黑羽-黑枪之布拉斯特」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(16516630, 'Blackwing - Boreas the Sharp', '黑羽-尖锐之布拉', 'BF－尖鋭のボーラ', 'Effect Monster', 'Winged Beast', 'DARK', 5, 1300, 900, '把墓地存在的这张卡从游戏中除外，选择自己场上表侧表示存在的1只名字带有「黑羽」的怪兽发动。这个回合选择的怪兽攻击的场合，那次攻击发生的对自己的战斗伤害变成0，选择的怪兽不会被战斗破坏，进行战斗的对方怪兽在伤害计算后破坏。'),
(10602628, 'Blackwing - Boreastorm the Wicked Wind', '黑羽－魔风之玻瑞阿斯', 'BF－魔風のボレアース', 'Synchro Tuner Monster', 'Winged Beast', 'DARK', 6, 2400, 1600, '暗属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1只「黑羽」怪兽送去墓地。这张卡的等级变成和那只怪兽的等级相同。 ②：这张卡战斗破坏怪兽送去墓地时，从自己的场上（表侧表示）·墓地把1只「黑羽」怪兽除外才能发动。那只破坏的怪兽在自己场上守备表示特殊召唤。'),
(89258906, 'Blackwing - Breeze the Zephyr', '黑羽-微风之布利兹', 'BF－そよ風のブリーズ', 'Tuner Monster', 'Winged Beast', 'DARK', 3, 1100, 300, '这张卡被魔法·陷阱·效果怪兽的效果从自己卡组加入手卡的场合，这张卡可以在自己场上特殊召唤。把这张卡作为同调素材的场合，不是名字带有「黑羽」的怪兽的同调召唤不能使用。'),
(52900379, 'Blackwing - Brisote the Tailwind', '黑羽-追风之艾莉婕', 'BF－追い風のアリゼ', 'Effect Monster', 'Winged Beast', 'DARK', 5, 1200, 1800, '自己场上表侧表示存在的名字带有「黑羽」的怪兽有2只以上被破坏的回合，这张卡可以从手卡特殊召唤。这张卡作为同调召唤的素材送去墓地的场合，自己回复600基本分。'),
(88305978, 'Blackwing - Calima the Haze', '黑羽-阳炎之卡姆', 'BF－陽炎のカーム', 'Effect Monster', 'Winged Beast', 'DARK', 4, 600, 1800, '对方的战斗阶段时，自己场上没有怪兽存在的场合，把墓地存在的这张卡从游戏中除外才能发动。选择自己墓地存在的1只同调怪兽特殊召唤。这个效果特殊召唤的怪兽在战斗阶段结束时从游戏中除外。'),
(34976176, 'Blackwing - Chinook the Snow Blast', '黑羽－雪击之奇努克', 'BF－雪撃のチヌーク', 'Effect Monster', 'Winged Beast', 'DARK', 2, 100, 700, '这个卡名的效果1回合只能使用1次。 ①：把手卡·场上的这张卡送去墓地，以对方场上1只表侧表示怪兽为对象才能发动（自己场上有暗属性同调怪兽存在的场合，这个效果在对方回合也能发动）。从额外卡组把1只「黑羽」同调怪兽或「黑翼龙」送去墓地，作为对象的怪兽直到回合结束时攻击力下降700，效果无效化。'),
(58131925, 'Blackwing - Damascus the Polar Night', '黑羽-极夜之大马士革刀鸟', 'BF－極夜のダマスカス', 'Effect Monster', 'Winged Beast', 'DARK', 3, 1300, 700, '①：把这张卡从手卡丢弃，以自己场上1只「黑羽」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。这个效果在对方回合也能发动。'),
(19462747, 'Blackwing - Decay the Ill Wind', '黑羽-吊风之戴思', 'BF－弔風のデス', 'Tuner Monster', 'Winged Beast', 'DARK', 4, 1000, 1000, '「黑羽-吊风之戴思」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时，可以以自己场上1只「黑羽」怪兽为对象，从以下效果选择1个发动。 ●作为对象的怪兽的等级上升1星。 ●作为对象的怪兽的等级下降1星。 ②：这张卡被送去墓地的回合的结束阶段发动。自己受到1000伤害。'),
(11613567, 'Blackwing - Elphin the Raven', '黑羽-漆黑之艾尔芬', 'BF－漆黒のエルフェン', 'Effect Monster', 'Winged Beast', 'DARK', 6, 2200, 1200, '自己场上有名字带有「黑羽」的怪兽表侧表示存在的场合，这张卡可以不用解放作召唤。这张卡召唤成功时，可以把对方场上存在的1只怪兽的表示形式改变。'),
(78564023, 'Blackwing - Etesian of Two Swords', '黑羽-二太刀之厄特西安', 'BF－二の太刀のエテジア', 'Effect Monster', 'Winged Beast', 'DARK', 3, 400, 1600, '自己场上存在的名字带有「黑羽」的怪兽进行和对方怪兽的战斗的伤害步骤结束时那只对方怪兽在场上存在的场合，把这张卡从手卡送去墓地才能发动。给与对方基本分1000分伤害。'),
(9109991, 'Blackwing - Fane the Steel Chain', '黑羽-铁锁之焚', 'BF－鉄鎖のフェーン', 'Effect Monster', 'Winged Beast', 'DARK', 2, 500, 800, '这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，对方场上攻击表示存在的1只怪兽变成守备表示。'),
(2009101, 'Blackwing - Gale the Whirlwind', '黑羽－疾风之盖尔', 'BF－疾風のゲイル', 'Tuner Monster', 'Winged Beast', 'DARK', 3, 1300, 400, '①：自己场上有「黑羽-疾风之盖尔」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力·守备力变成一半。'),
(26775203, 'Blackwing - Ghibli the Searing Wind', '黑羽-热风之基布利', 'BF－熱風のギブリ', 'Effect Monster', 'Winged Beast', 'DARK', 3, NULL, 1600, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。这张卡的原本的攻击力·守备力直到回合结束时交换。'),
(28190303, 'Blackwing - Gladius the Midnight Sun', '黑羽-白夜之短剑鸟', 'BF－白夜のグラディウス', 'Effect Monster', 'Winged Beast', 'DARK', 3, 800, 1500, '①：自己场上的表侧表示怪兽只有「黑羽-白夜之短剑鸟」以外的「黑羽」怪兽1只的场合，这张卡可以从手卡特殊召唤。 ②：这张卡1回合只有1次不会被战斗破坏。'),
(9929398, 'Blackwing - Gofu the Vague Shadow', '黑羽-胧影之业风', 'BF－朧影のゴウフウ', 'Tuner Monster', 'Winged Beast', 'DARK', 5, NULL, NULL, '这张卡不能通常召唤。自己场上没有怪兽存在的场合可以特殊召唤。 ①：这张卡从手卡的特殊召唤成功时才能发动。在自己场上把2只「胧影衍生物」（鸟兽族·暗·1星·攻/守0）特殊召唤。这衍生物不能解放，不能作为同调素材。 ②：把这张卡和除调整以外的怪兽1只以上从自己场上除外，以持有和那个等级合计相同等级的自己墓地1只「黑羽」同调怪兽为对象才能发动。那只怪兽当作调整使用特殊召唤。'),
(17377751, 'Blackwing - Gram the Shining Star', '黑羽－煌星之格拉墨', 'BF－煌星のグラム', 'Synchro Monster', 'Winged Beast', 'DARK', 5, 2200, 1500, '调整＋调整以外的怪兽1只以上 这张卡用同调召唤才能从额外卡组特殊召唤。这张卡同调召唤成功时，可以从手卡把1只调整以外的4星以下的名字带有「黑羽」的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(52869807, 'Blackwing - Gust the Backblast', '黑羽－逆风之加斯特', 'BF－逆風のガスト', 'Effect Monster', 'Winged Beast', 'DARK', 2, 900, 1400, '自己场上没有卡存在的场合，这张卡可以从手卡特殊召唤。只要这张卡在场上表侧表示存在，对方怪兽向自己场上存在的名字带有「黑羽」的怪兽攻击的场合，那只攻击怪兽在伤害步骤内攻击力下降300。'),
(77152542, 'Blackwing - Harmattan the Dust', '黑羽－沙尘之哈马丹', 'BF－砂塵のハルマッタン', 'Effect Monster', 'Winged Beast', 'DARK', 2, 800, 800, '「黑羽-沙尘之哈麦丹」的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「黑羽-沙尘之哈麦丹」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功时，以这张卡以外的自己场上1只「黑羽」怪兽为对象才能发动。这张卡的等级上升那只怪兽的等级数值。'),
(3072808, 'Blackwing - Hillen the Tengu-wind', '黑羽-天狗风之飞廉', 'BF－天狗風のヒレン', 'Tuner Monster', 'Winged Beast', 'DARK', 5, NULL, 2300, '这张卡在墓地存在，对方怪兽的直接攻击让自己受到2000以上的战斗伤害时，选择自己墓地存在的1只名字带有「黑羽」的3星以下的怪兽发动。选择的怪兽和这张卡从墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「黑羽-天狗风之飞廉」的效果在决斗中只能使用1次。'),
(36442179, 'Blackwing - Hurricane the Tornado', '黑羽-龙卷之哈里肯', 'BF－竜巻のハリケーン', 'Tuner Monster', 'Winged Beast', 'DARK', 1, NULL, NULL, '①：1回合1次，以场上1只同调怪兽为对象才能发动。这张卡的攻击力直到回合结束时变成和作为对象的怪兽的攻击力相同。'),
(87390067, 'Blackwing - Jetstream the Blue Sky', '黑羽-苍天之捷特', 'BF－蒼天のジェット', 'Effect Monster', 'Winged Beast', 'DARK', 1, 100, 800, '战斗伤害计算时，把这张卡从手卡送去墓地发动。自己场上存在的名字带有「黑羽」的怪兽不会被那次战斗破坏。'),
(38562933, 'Blackwing - Jin the Rain Shadow', '黑羽-空风之精', 'BF－空風のジン', 'Tuner Monster', 'Winged Beast', 'DARK', 1, 600, 500, '和持有这张卡的攻击力以下的守备力的场上表侧表示存在的怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。'),
(85215458, 'Blackwing - Kalut the Moon Shadow', '黑羽－月影之卡鲁特', 'BF－月影のカルート', 'Effect Monster', 'Winged Beast', 'DARK', 3, 1400, 1000, '①：自己的「黑羽」怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只怪兽的攻击力直到回合结束时上升1400。'),
(41902352, 'Blackwing - Kochi the Daybreak', '黑羽-东云之东风', 'BF－東雲のコチ', 'Tuner Monster', 'Winged Beast', 'DARK', 4, 700, 1500, '特殊召唤的这张卡不能作为同调素材。'),
(49460512, 'Blackwing - Kogarashi the Wanderer', '黑羽-流离之木枯', 'BF－流離いのコガラシ', 'Tuner Monster', 'Winged Beast', 'DARK', 6, 2300, 1600, '自己场上表侧表示存在的名字带有「黑羽」的怪兽被卡的效果破坏送去墓地时，这张卡可以从手卡特殊召唤。此外，这张卡为同调素材的同调召唤成功时，对方不能把魔法·陷阱·效果怪兽的效果发动。'),
(81105204, 'Blackwing - Kris the Crack of Dawn', '黑羽－残夜之酷利斯', 'BF－残夜のクリス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1900, 300, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「黑羽-残夜之波刃剑鸟」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡1回合只有1次不会被魔法·陷阱卡的效果破坏。'),
(46710683, 'Blackwing - Mistral the Silver Shield', '黑羽-银盾之密史脱拉', 'BF－銀盾のミストラル', 'Tuner Monster', 'Winged Beast', 'DARK', 2, 100, 1800, '场上存在的这张卡被破坏送去墓地的场合，这个回合自己受到的战斗伤害只有1次变成0。'),
(95040215, 'Blackwing - Nothung the Starlight', '黑羽－星影之诺顿克', 'BF－星影のノートゥング', 'Synchro Monster', 'Winged Beast', 'DARK', 6, 2400, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合发动。给与对方800伤害。那之后，对方场上1只表侧表示怪兽的攻击力·守备力下降800。 ②：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「黑羽」怪兽召唤。'),
(73652465, 'Blackwing - Oroshi the Squall', '黑羽－突风之风落袭', 'BF－突風のオロシ', 'Tuner Monster', 'Winged Beast', 'DARK', 1, 400, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「黑羽-突风之颪」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡作为同调素材送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(55610595, 'Blackwing - Pinaki the Waxing Moon', '黑羽－上弦之比那卡', 'BF－上弦のピナーカ', 'Tuner Monster', 'Winged Beast', 'DARK', 3, 1200, 1000, '「黑羽-上弦之灭弓鸟」的效果1回合只能使用1次。把这张卡作为同调素材的场合，不是「黑羽」怪兽的同调召唤不能使用。 ①：这张卡从场上送去墓地的回合的结束阶段才能发动。从卡组把「黑羽-上弦之灭弓鸟」以外的1只「黑羽」怪兽加入手卡。'),
(8571567, 'Blackwing - Shamal the Sandstorm', '黑羽－岚砂之夏马尔', 'BF－嵐砂のシャマール', 'Tuner Monster', 'Winged Beast', 'DARK', 4, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地才能发动。从卡组把1张「黑羽之旋风」在自己场上表侧表示放置。 ②：这张卡在墓地存在的状态，自己场上有「黑羽」同调怪兽或「黑翼龙」特殊召唤的场合，把这张卡除外，以自己墓地1只「黑羽」怪兽为对象才能发动。那只怪兽加入手卡。那之后，自己受到700伤害。'),
(54594017, 'Blackwing - Sharnga the Waning Moon', '黑羽－下弦之萨伦伽', 'BF－下弦のサルンガ', 'Tuner Monster', 'Winged Beast', 'DARK', 2, 500, 500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果在决斗中只能使用1次。 ①：场上有攻击力2000以上的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方回合，自己场上有「黑羽」同调怪兽存在的场合，把墓地的这张卡除外，以对方场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(58820853, 'Blackwing - Shura the Blue Flame', '黑羽－苍炎之修罗', 'BF－蒼炎のシュラ', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1800, 1200, '①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只攻击力1500以下的「黑羽」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(33236860, 'Blackwing - Silverwind the Ascendant', '黑羽－孤高之银风', 'BF－孤高のシルバー・ウィンド', 'Synchro Monster', 'Winged Beast', 'DARK', 8, 2800, 2000, '「黑羽」调整＋调整以外的怪兽2只以上 ①：这张卡同调召唤时，以场上最多2只表侧表示怪兽为对象才能发动（这个效果发动的回合，自己不能进行战斗阶段）。持有比这张卡的攻击力低的守备力的作为对象的怪兽破坏。 ②：只要这张卡在怪兽区域存在，对方回合只有1次，自己的「黑羽」怪兽不会被战斗破坏。'),
(81470373, 'Blackwing - Simoon the Poison Wind', '黑羽－毒风之砂蒙', 'BF－毒風のシムーン', 'Effect Monster', 'Winged Beast', 'DARK', 6, 1600, 2000, '这个卡名的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，从手卡把这张卡以外的1只「黑羽」怪兽除外才能发动。从卡组选1张「黑旋风」在自己的魔法与陷阱区域表侧表示放置。那之后，手卡的这张卡不用解放作召唤或送去墓地。这个效果放置的「黑旋风」在结束阶段送去墓地，自己受到1000伤害。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能从额外卡组特殊召唤。'),
(75498415, 'Blackwing - Sirocco the Dawn', '黑羽－晓之西洛可', 'BF－暁のシロッコ', 'Effect Monster', 'Winged Beast', 'DARK', 5, 2000, 900, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以不用解放作通常召唤。 ②：1回合1次，自己主要阶段1以自己场上1只「黑羽」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升那只怪兽以外的场上的「黑羽」怪兽的攻击力的合计数值。这个效果发动的回合，不用作为对象的怪兽不能攻击。'),
(9047460, 'Blackwing - Steam the Cloak', '黑羽－隐蓑之斯汽姆', 'BF－隠れ蓑のスチーム', 'Tuner Monster', 'Winged Beast', 'DARK', 3, 800, 1200, '「黑羽-隐身蓑之斯蒂姆」的②的效果在决斗中只能使用1次。 ①：表侧表示的这张卡从场上离开的场合发动。在自己场上把1只「蒸汽衍生物」（水族·风·1星·攻/守100）特殊召唤。 ②：这张卡在墓地存在的场合，把自己场上1只怪兽解放才能发动。这张卡从墓地特殊召唤。把这个效果特殊召唤的这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是「黑羽」怪兽。'),
(70465810, 'Blackwing - Sudri the Phantom Glimmer', '黑羽－幻耀之苏德里', 'BF－幻耀のスズリ', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1400, 1400, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。除「黑羽-幻耀之苏德里」外的1张有「黑翼龙」的卡名记述的卡从卡组加入手卡。 ②：把自己场上1只怪兽解放才能发动（这个效果发动的回合，自己不是同调怪兽不能从额外卡组特殊召唤）。在自己场上把1只「幻耀衍生物」（鸟兽族·调整·暗·2星·攻/守700）特殊召唤。那之后，自己受到700伤害。'),
(73534250, 'Blackwing - Tornado the Reverse Wind', '黑羽-逆卷之托纳多', 'BF－逆巻のトルネード', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1000, 1200, '①：特殊召唤的怪兽在对方场上存在，这张卡召唤成功时，以自己墓地1只「黑羽」调整为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是「黑羽」怪兽不能从额外卡组特殊召唤。'),
(69973414, 'Blackwing - Twin Shadow', '黑羽－双影', 'BF－ツインシャドウ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己场上有「黑羽」怪兽2只以上存在的场合，这张卡的发动从手卡也能用。 ①：让自己的墓地·除外状态的「黑羽」调整1只和调整以外的「黑羽」怪兽1只回到卡组·额外卡组才能发动。把持有和那2只的等级合计相同等级的1只「黑羽」同调怪兽或「黑翼龙」当作同调召唤从额外卡组特殊召唤。'),
(71187462, 'Blackwing - Vata the Emblem of Wandering', '黑羽－无赖之伐他', 'BF－無頼のヴァータ', 'Tuner Monster', 'Winged Beast', 'DARK', 2, 800, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「黑羽-无赖之伐他」以外的「黑羽」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。等级合计直到8的这张卡和除调整以外的卡组的「黑羽」怪兽1只以上送去墓地，把1只「黑翼龙」从额外卡组特殊召唤。这个回合，自己不是暗属性怪兽不能从额外卡组特殊召唤。'),
(72714392, 'Blackwing - Vayu the Emblem of Honor', '黑羽－大旆之伐由', 'BF－大旆のヴァーユ', 'Tuner Monster', 'Winged Beast', 'DARK', 1, 800, NULL, '①：这张卡只要在怪兽区域存在，不能作为同调素材。 ②：这张卡在墓地存在的场合，以调整以外的自己墓地1只「黑羽」怪兽为对象才能发动。那只怪兽和这张卡从墓地除外，把持有和那2只的等级合计相同等级的1只「黑羽」同调怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(14785765, 'Blackwing - Zephyros the Elite', '黑羽－精锐之仄费罗斯', 'BF－精鋭のゼピュロス', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1600, 1000, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡在墓地存在的场合，让自己场上1张表侧表示卡回到手卡才能发动。这张卡特殊召唤，自己受到400伤害。'),
(7459919, 'Blackwing - Zonda the Dusk', '黑羽－刻夜之佐达', 'BF－刻夜のゾンダ', 'Effect Monster', 'Winged Beast', 'DARK', 6, 2300, 900, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：只要这张卡在怪兽区域存在，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。 ③：把墓地的这张卡除外才能发动。从手卡·卡组把1只5星以上的「黑羽」怪兽特殊召唤。那之后，自己受到这个效果特殊召唤的怪兽的攻击力数值的伤害。'),
(76913983, 'Blackwing Armed Wing', '黑羽－武装之翼', 'BF－アームズ・ウィング', 'Synchro Monster', 'Winged Beast', 'DARK', 6, 2300, 1000, '「黑羽」调整＋调整以外的怪兽1只以上 ①：这张卡向守备表示怪兽攻击的伤害步骤内，这张卡的攻击力上升500。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(69031175, 'Blackwing Armor Master', '黑羽－装甲之翼', 'BF－アーマード・ウィング', 'Synchro Monster', 'Winged Beast', 'DARK', 7, 2500, 1500, '「黑羽」调整＋调整以外的怪兽1只以上 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：这张卡向怪兽攻击的伤害步骤结束时才能发动。给那只怪兽放置1个楔指示物（最多1个）。 ③：把对方场上的楔指示物全部取除才能发动。有楔指示物放置过的全部怪兽的攻击力·守备力直到回合结束时变成0。'),
(54082269, 'Blackwing Full Armor Master', '黑羽－全装甲之翼', 'BF－フルアーマード・ウィング', 'Synchro Monster', 'Winged Beast', 'DARK', 10, 3000, 3000, '「黑羽」调整＋调整以外的怪兽1只以上 ①：场上的这张卡不受其他卡的效果影响。 ②：只要这张卡在怪兽区域存在，每次对方场上的怪兽把效果发动，给那只对方的表侧表示怪兽放置1个楔指示物（最多1个）。 ③：1回合1次，以对方场上1只有楔指示物放置的怪兽为对象才能发动。得到那只怪兽的控制权。 ④：自己结束阶段才能发动。有楔指示物放置的怪兽全部破坏。'),
(81983656, 'Blackwing Tamer - Obsidian Hawk Joe', '黑羽驯鸟师－漆黑之鹰匠', 'BF T－漆黒のホーク・ジョー', 'Synchro Monster', 'Warrior', 'DARK', 7, 2600, 2000, '「黑羽」调整＋调整以外的「黑羽」怪兽1只以上 「黑羽驯鸟师-漆黑之鹰匠·乔」的①②的效果1回合各能使用1次。 ①：以自己墓地1只5星以上的鸟兽族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡成为对方的效果的对象时或者成为对方怪兽的攻击对象时，以这张卡以外的自己场上1只「黑羽」怪兽为对象才能发动。那个对象转移为作为正确对象的那只怪兽。'),
(82944432, 'Blade Armor Ninja', '机甲忍者 刃心', '機甲忍者ブレード・ハート', 'XYZ Monster', 'Warrior', 'WIND', 4, 2200, 1000, '战士族4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只「忍者」怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(70194827, 'Blade Bounzer', '利刃保镖', 'ブレード・バウンサー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1400, '这张卡进行攻击的伤害步骤结束时，对方场上有怪兽存在的场合，丢弃1张手卡才能发动。这次战斗阶段中，这张卡只有1次可以向对方怪兽再攻击。这个效果1回合只能使用1次。'),
(78509901, 'Blade Garoodia the Cubic Beast', '方界兽 利刃之迦楼迪亚', '方界獣ブレード・ガルーディア', 'Effect Monster', 'Beast', 'FIRE', 3, NULL, NULL, '这张卡不能通常召唤。把自己场上2只「方界」怪兽送去墓地的场合可以特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升2000。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：这张卡战斗破坏怪兽时，以自己墓地最多3只「方界胤 毗贾姆」为对象才能发动。这张卡送去墓地，作为对象的怪兽特殊召唤。那之后，可以从卡组把1只「方界超兽 破坏之乾闼尔」加入手卡。'),
(39507162, 'Blade Knight', '刀锋骑士', 'ブレイドナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1000, '①：只要自己手卡是1张以下，这张卡的攻击力上升400。 ②：自己场上没有这张卡以外的怪兽存在的场合，这张卡战斗破坏的反转怪兽的效果无效化。'),
(58268433, 'Blade Rabbit', '剑齿兔', 'ブレードラビット', 'Effect Monster', 'Beast', 'EARTH', 2, 400, 300, '这张卡的表示形式从攻击表示变成表侧守备表示时，破坏对方场上1只怪兽。'),
(97023549, 'Blade Skater', '利刃滑冰者', 'ブレード・スケーター', 'Normal Monster', 'Warrior', 'EARTH', 4, 1400, 1500, '冰上的舞姬是华丽的战士。以必杀技阿克塞尔切裂华丽地把敌人怪兽切裂。'),
(28470714, 'Bladefly', '刃蝇', 'ブレードフライ', 'Effect Monster', 'Insect', 'WIND', 2, 600, 700, '只要这张卡在场上表侧表示存在，全部风属性的怪兽攻击力上升500。地属性的怪兽攻击力下降400。'),
(11685347, 'Blast Asmodian', '连爆魔人', '連爆魔人', 'Effect Monster', 'Fiend', 'FIRE', 3, 1000, 300, '有魔法·陷阱卡连锁的场合，给与对方基本分500分伤害。'),
(89041555, 'Blast Held by a Tribute', '牲祭怀抱的爆弹', '生贄の抱く爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：上级召唤的对方怪兽的攻击宣言时才能发动。对方场上的表侧攻击表示怪兽全部破坏，给与对方1000伤害。'),
(51208877, 'Blast Held by Destiny', '命运怀抱的爆弹', '運命の抱く爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。对方场上1只攻击力最高的怪兽破坏，给与对方那个原本攻击力数值的伤害。自己墓地没有「现世与冥界的逆转」存在的场合，再让自己受到和对方受到的伤害相同数值的伤害。 ②：这张卡从手卡·卡组送去墓地的场合，以自己墓地1只天使族·地属性·4星怪兽为对象才能发动。那只怪兽加入手卡。'),
(70138455, 'Blast Juggler', '炸弹先生', 'ミスター・ボンバー', 'Effect Monster', 'Machine', 'FIRE', 3, 800, 900, '在自己的准备阶段时发动。表侧表示的这张卡作为祭品，选择2只表侧表示的攻击力1000以下的怪兽破坏。'),
(21051146, 'Blast Magician', '血魔术师-炼狱的魔术师-', 'ブラッド・マジシャン－煉獄の魔術師－', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1400, 1700, '只要这张卡在场上表侧表示存在，每次自己或者对方把魔法卡发动，给这张卡放置魔力指示物。可以把这张卡放置的魔力指示物任意数量取除，持有取除数量×700的数值以下的攻击力的场上表侧表示存在的1只怪兽破坏。'),
(26302522, 'Blast Sphere', '球体时限炸弹', 'スフィア・ボム 球体時限爆弾', 'Effect Monster', 'Machine', 'DARK', 4, 1400, 1400, '①：里侧守备表示的这张卡被对方怪兽攻击的伤害计算前发动。这张卡当作装备卡使用给那只攻击怪兽装备。 ②：用这张卡的效果把这张卡装备的下次的对方准备阶段发动。装备怪兽破坏，给与对方那个攻击力数值的伤害。'),
(98239899, 'Blast with Chain', '附锁链的爆弹', '鎖付き爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能把这张卡发动。这张卡当作攻击力上升500的装备卡使用给那只自己怪兽装备。 ②：当作装备卡使用的这张卡被效果破坏的场合，以场上1张卡为对象发动。那张卡破坏。'),
(53804307, 'Blaster, Dragon Ruler of Infernos', '焰征龙－爆破', '焔征竜－ブラスター', 'Effect Monster', 'Dragon', 'FIRE', 7, 2800, 1800, '这个卡名的①～④的效果1回合只能有1次使用其中任意1个。 ①：从手卡把这张卡和1只炎属性怪兽丢弃去墓地，以场上1张卡为对象才能发动。那张破坏。 ②：把2只龙族或炎属性的怪兽从自己的手卡·墓地除外才能发动。这张卡从手卡·墓地特殊召唤。 ③：这张卡特殊召唤的场合，对方结束阶段发动。这张卡回到手卡。 ④：这张卡被除外的场合才能发动。从卡组把1只龙族·炎属性怪兽加入手卡。'),
(99788587, 'Blasting Fuse', '爆导索', '爆導索', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：和这张卡相同纵列全部有卡存在的场合才能把盖放的这张卡发动。那个纵列的卡全部破坏。'),
(21466326, 'Blasting the Ruins', '残骸爆破', '残骸爆破', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当自己墓地里存在30张以上卡的场合这张卡才能发动。给与对方基本分3000分的伤害。'),
(69537999, 'Blaze Accelerator', '烈焰加农炮', 'ブレイズ・キャノン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以对方场上1只怪兽为对象才能把这个效果发动（这个效果发动的回合，自己怪兽不能攻击）。从手卡把1只攻击力500以下的炎族怪兽送去墓地，作为对象的对方怪兽破坏。'),
(300302024, 'Blaze Accelerator Deployment (Skill Card)', NULL, NULL, 'Skill Card', 'Axel Brodie', NULL, NULL, NULL, NULL, NULL),
(52198054, 'Blaze Accelerator Reload', '烈焰加农炮弹匣', 'ブレイズ・キャノン・マガジン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在魔法与陷阱区域存在当作「烈焰加农炮-三叉戟式」使用。 ②：自己·对方的主要阶段才能发动。从手卡把1张「火山」卡送去墓地，自己抽1张。 ③：自己·对方的主要阶段，把墓地的这张卡除外才能发动。从卡组把1张「火山」卡送去墓地。'),
(4059313, 'Blaze Cannon', '神威烈焰加农炮', 'ゴッド・ブレイズ・キャノン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：选自己场上1只「太阳神之翼神龙」。那只怪兽直到回合结束时得到以下效果。这张卡的发动和效果不会被无效化。 ●这张卡不受对方的效果影响。 ●这张卡进行战斗的攻击宣言时，把这个回合没有攻击宣言的自己场上的其他怪兽任意数量解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的原本攻击力的合计数值。 ●这张卡攻击的伤害计算后才能发动。对方场上的怪兽全部送去墓地。'),
(6602300, 'Blaze Fenix, the Burning Bombardment Bird', '重爆击禽 炸弹不死魔鸟', '重爆撃禽 ボム・フェネクス', 'Fusion Monster', 'Pyro', 'FIRE', 8, 2800, 2300, '机械族怪兽＋炎族怪兽 自己的主要阶段时，可以给与对方基本分场上存在的卡每1张300分伤害。这个效果发动的回合这张卡不能攻击。这个效果1回合只能使用1次。'),
(47132793, 'Blaze, Supreme Ruler of all Dragons', '征霸龙－烈焰', '征覇竜－ブレイズ', 'XYZ Monster', 'Dragon', 'FIRE', 7, 2800, 1800, '7星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己的手卡·场上1张卡和对方场上1张卡破坏。 ②：把2只龙族或炎属性的怪兽从自己的手卡·墓地除外才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到额外卡组。'),
(16984449, 'Blazewing Butterfly', '炎妖蝶 维尔普斯', '炎妖蝶ウィルプス', 'Gemini Monster', 'Insect', 'FIRE', 4, 1500, 1500, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●把这张卡解放，以「炎妖蝶 维尔普斯」以外的自己墓地1只二重怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽当作再1次召唤的状态使用。'),
(70117791, 'Blazing Bombardment Beast', '爆击兽 炎弹兽', '爆撃獣ファイヤ・ボンバー', 'Fusion Monster', 'Machine', 'FIRE', 6, 1900, 2400, '机械族怪兽＋炎族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。对方场上的攻击力1900以下的怪兽全部破坏。 ②：这张卡被送去墓地的场合，以对方场上1只攻击力1900以下的怪兽为对象才能发动。那只怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(95515789, 'Blazing Cartesia, the Virtuous', '赫之圣女 卡尔塔西亚', '赫の聖女カルテシア', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己的场上或墓地有「阿不思的落胤」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方的主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只8星以上的融合怪兽融合召唤。 ③：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。'),
(92518817, 'Blazing Hiita', '盛燃之希塔', '燃え盛るヒータ', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 800, 1500, '可以把自己场上除这张卡以外的1只炎属性怪兽做祭品，从手卡特殊召唤1只炎属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「盛燃之希塔」从自己场上离开的场合破坏。'),
(5464695, 'Blazing Inpachi', '火炎木人18', '火炎木人１８', 'Normal Monster', 'Pyro', 'FIRE', 4, 1850, NULL, '全身被灼热火焰吞没的巨木化身。火焰攻击虽然强力，但由于自身着火所以时日不多了。'),
(75249652, 'Blazing Mirror Force', '业炎防护罩 -火焰之力-', '業炎のバリア －ファイヤー・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的攻击表示怪兽全部破坏，自己受到这个效果破坏的怪兽的原本攻击力合计数值一半的伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。'),
(15177750, 'Blessed Winds', '惠畅之风', '恵みの風', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●从自己的手卡·场上（表侧表示）把1只植物族怪兽送去墓地才能发动。自己回复500基本分。 ●以自己墓地1只植物族怪兽为对象才能发动。那只怪兽回到卡组。那之后，自己回复500基本分。 ●支付1000基本分才能发动。从自己墓地把1只「芳香」怪兽特殊召唤。'),
(39114494, 'Blessing of the Voiceless Voice', '肃声祝福', '粛声なる祝福', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以「肃声之祝福」以外的自己的墓地·除外状态的1张「肃声」卡为对象才能发动。那张卡加入手卡。 ②：仪式怪兽以外的怪兽表侧表示召唤·特殊召唤的场合才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只战士族·龙族而光属性的仪式怪兽仪式召唤。这个效果特殊召唤的怪兽不会被战斗破坏。'),
(82422049, 'Blessings for Gusto', '对薰风的祈祷', 'ガスタへの祈り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的2只名字带有「薰风」的怪兽，加入卡组洗切。那之后，选择自己墓地存在的1只名字带有「薰风」的怪兽特殊召唤。'),
(30653113, 'Blessings of the Nile', '尼罗河的恩惠', 'ナイルの恵み', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每当因对方所控制的卡的效果使自己的手卡被弃进墓地时，自己回复1000基本分。'),
(32015116, 'Blind Destruction', '无差别破坏', '無差別破壊', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段丢1次骰子。和投出来的数目一样等级的怪兽全部破坏。（投出来的数目是6的场合包括6星以上的怪兽）'),
(22802010, 'Blind Obliteration', '无差别崩坏', '無差別崩壊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：掷2次骰子。等级·阶级比出现的数目合计低的场上的表侧表示怪兽全部破坏。'),
(49267971, 'Blind Spot Strike', '来自死角的一击', '死角からの一撃', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择对方场上表侧守备表示存在的1只怪兽和自己场上表侧攻击表示存在的1只怪兽发动。选择的自己怪兽的攻击力直到结束阶段时上升选择的对方怪兽的守备力数值。'),
(35215622, 'Blindly Loyal Goblin', '盲信的哥布林', '盲信するゴブリン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1500, '只要这张卡在场上表侧表示存在，控制权不会被转移。'),
(28279365, 'Blink Out', '闪瞬连倒', 'ブリンクアウト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只连接怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，可以把已作为那只怪兽的连接素材送去自己墓地的1只怪兽特殊召唤。'),
(51706604, 'Blizzard', '雪暴', 'ブリザード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1张表侧表示的魔法卡为对象才能发动。这个回合，那张卡以及原本卡名和那张卡相同的魔法卡在场上发动的效果无效化。这个回合中作为对象的卡被送去对方墓地的场合，不去墓地回到对方手卡。'),
(61802346, 'Blizzard Dragon', '雪暴龙', 'ブリザード・ドラゴン', 'Effect Monster', 'Dragon', 'WATER', 4, 1800, 1000, '选择对方场上存在的1只怪兽。选择怪兽直到下次对方回合的结束阶段时，不能作表示形式的改变和攻击宣言。这个效果1回合只能使用1次。'),
(43694481, 'Blizzard Falcon', '雪暴猎鹰', 'ブリザード・ファルコン', 'Effect Monster', 'Winged Beast', 'WATER', 4, 1500, 1500, '这张卡的攻击力比原本攻击力高的场合才能发动。给与对方基本分1500分伤害。这个效果只在这张卡在场上表侧表示存在能使用1次，「雪暴猎鹰」的效果1回合只能使用1次。'),
(28348537, 'Blizzard Princess', '暴风雪公主', 'ブリザード・プリンセス', 'Effect Monster', 'Spellcaster', 'WATER', 8, 2800, 2100, '这张卡可以把1只魔法师族怪兽解放表侧攻击表示上级召唤。这张卡召唤成功的回合，对方不能把魔法·陷阱卡发动。'),
(50920465, 'Blizzard Thunderbird', '雪暴雷鸟', 'ブリザード・サンダーバード', 'Effect Monster', 'Winged Beast', 'WATER', 4, 1600, 1400, '丢弃1张手卡才能发动。「雪暴雷鸟」以外的鸟兽族·水属性怪兽从自己的手卡·墓地各选1只特殊召唤。那之后，场上的这张卡回到持有者手卡。「雪暴雷鸟」的效果1回合只能使用1次。'),
(96565487, 'Blizzard Warrior', '暴风雪战士', 'ブリザード・ウォリアー', 'Effect Monster', 'Warrior', 'WATER', 3, 1400, 400, '①：这张卡战斗破坏对方怪兽的场合发动。把对方卡组最上面的卡确认，回到卡组最上面或最下面。'),
(60161788, 'Blizzed, Defender of the Ice Barrier', '冰结界的看守 布力兹德', '氷結界の番人 ブリズド', 'Effect Monster', 'Aqua', 'WATER', 1, 300, 500, '①：这张卡被战斗破坏送去墓地的场合发动。自己抽1张。'),
(25880422, 'Block Attack', '『攻击』封禁', '『攻撃』封じ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '指定的对方场上的1只表侧表示的怪兽转为守备表示。'),
(94689206, 'Block Dragon', '积木龙', 'ブロックドラゴン', 'Effect Monster', 'Rock', 'EARTH', 8, 2500, 3000, '这张卡不能通常召唤。把自己的手卡·墓地3只地属性怪兽除外的场合才能从手卡·墓地特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的岩石族怪兽不会被战斗以外破坏。 ②：这张卡从场上送去墓地的场合才能发动。等级合计直到变成8星为止，从卡组把最多3只岩石族怪兽加入手卡。'),
(72580321, 'Block Golem', '积木巨人', 'ブロック・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 3, 1000, 1500, '①：自己墓地的怪兽只有地属性的场合，把这张卡解放，以「积木巨人」以外的自己墓地2只4星以下的岩石族怪兽为对象才能发动。那些岩石族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把场上发动的效果发动。'),
(79636594, 'Block Spider', '积木蜘蛛', 'ブロック・スパイダー', 'Effect Monster', 'Insect', 'EARTH', 1, NULL, 100, '「积木蜘蛛」的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能把其他的昆虫族怪兽作为攻击对象。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1只「积木蜘蛛」特殊召唤。'),
(48115278, 'Block Token', '积木人', 'ブロックマン', 'Token', 'Rock', NULL, NULL, NULL, NULL, NULL),
(34743446, 'Blocker', '碎块人', 'ブロッカー', 'Normal Monster', 'Machine', 'DARK', 4, 850, 1800, '身体部件各为武器，分裂发动袭击。'),
(48115277, 'Blockman', '积木人', 'ブロックマン', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 1500, '①：把这张卡解放才能发动。和这张卡在自己场上表侧表示存在的自己回合数相同数量的「积木衍生物」（岩石族·地·4星·攻1000/守1500）在自己场上守备表示特殊召唤。这衍生物不能攻击宣言。'),
(53167658, 'Blockout Curtain', '遮攻幕帘', '遮攻カーテン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的卡被战斗或者对方的效果破坏的场合，可以作为那1张破坏的卡的代替而把这张卡破坏。 ②：对方场上的卡被战斗·效果破坏的场合，可以作为那1张破坏的卡的代替而把墓地的这张卡除外。'),
(30757396, 'Blood Mefist', '血魔 墨非斯特', 'ブラッド・メフィスト', 'Synchro Monster', 'Fiend', 'DARK', 8, 2800, 1300, '调整＋调整以外的怪兽1只以上 对方的准备阶段时，可以给与对方基本分对方场上存在的卡每1张300分伤害。此外，对方把魔法·陷阱卡盖放时，给与对方基本分300分伤害。'),
(97783659, 'Blood Sucker', '吸血者', 'ブラッド・サッカー', 'Effect Monster', 'Zombie', 'DARK', 4, 1300, 1500, '这张卡给与对方基本分战斗伤害时，从对方卡组上面把1张卡送去墓地。'),
(84988419, 'Bloom Diva the Melodious Choir', '幻奏华歌圣 绽放名伶', '幻奏の華歌聖ブルーム・ディーヴァ', 'Fusion Monster', 'Fairy', 'LIGHT', 6, 1000, 2000, '「幻奏的音姬」怪兽＋「幻奏」怪兽 ①：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：这张卡和特殊召唤的怪兽进行战斗的伤害计算后才能发动。给与对方那只对方怪兽和这张卡的原本攻击力差的数值的伤害，那只对方怪兽破坏。'),
(34974462, 'Bloom Harmonist the Melodious Composer', '幻奏华乐圣 绽放谐曲家', '幻奏の華楽聖ブルーム・ハーモニスト', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1000, NULL, '天使族怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合，丢弃1张手卡才能发动。从卡组把2只等级不同的「幻奏」怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。这个效果发动的回合，自己不是「幻奏」怪兽不能特殊召唤。 ②：这张卡所连接区的「幻奏」怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(24672164, 'Bloom Prima the Melodious Choir', '幻奏华歌圣 绽放首席', '幻奏の華歌聖ブルーム・プリマ', 'Fusion Monster', 'Fairy', 'LIGHT', 7, 1900, 2000, '「幻奏的音姬」怪兽＋「幻奏」怪兽1只以上 ①：这张卡的攻击力上升作为这张卡的融合素材的怪兽数量×300。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：融合召唤的这张卡被送去墓地的场合，以自己墓地1只「幻奏」怪兽为对象才能发动。那只怪兽加入手卡。'),
(99092624, 'Blooming of the Darkest Rose', '漆黑蔷薇之开华', '漆黒の薔薇の開華', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把最多有双方的场地区域的卡以及墓地的场地魔法卡数量的「蔷薇衍生物」（植物族·暗·2星·攻/守800）在自己·对方场上守备表示特殊召唤。 ②：这张卡在墓地存在的场合，以自己场上1只「黑蔷薇龙」或者植物族怪兽为对象才能发动。那只怪兽除外，这张卡回到卡组最下面。这个效果除外的怪兽在下次的准备阶段回到场上。'),
(13438207, 'Blossom Bombardment', '花朵炸弹', 'ブロッサム・ボンバー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的植物族怪兽战斗破坏对方怪兽送去墓地时才能发动。给与对方基本分那次战斗破坏的怪兽的攻击力数值的伤害。'),
(25551951, 'Blowback Dragon', '回膛手枪龙', 'ブローバック・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 6, 2300, 1200, '①：1回合1次，以对方场上1张卡为对象才能发动。进行3次投掷硬币，那之内2次以上是表的场合，那张对方的卡破坏。'),
(14568951, 'Blue Dragon Ninja', '青龙忍者', '青竜の忍者', 'Effect Monster', 'Sea Serpent', 'WATER', 5, 2100, 1200, '1回合1次，从手卡丢弃1只名字带有「忍者」的怪兽和1张名字带有「忍法」的卡，选择对方场上表侧表示存在的1只怪兽才能发动。这个回合，选择的怪兽不能攻击，效果无效化。这个效果在对方回合也能发动。'),
(55969226, 'Blue Dragon Summoner', '青龙召唤士', '青竜の召喚士', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1500, 600, '①：这张卡从场上送去墓地的场合才能发动。从卡组把1只龙族·战士族·魔法师族的通常怪兽加入手卡。'),
(40217358, 'Blue Duston', '蓝尘妖', 'ブルー・ダストン', 'Effect Monster', 'Fiend', 'WATER', 1, NULL, 1000, '这张卡不能解放，也不能作为融合·同调·超量召唤的素材。场上的这张卡被破坏时，这张卡的控制者的手卡随机选1张直到下个回合的准备阶段时里侧表示从游戏中除外。「蓝尘妖」在自己场上只能有1只表侧表示存在。'),
(50903514, 'Blue Flame Swordsman', '苍炎之剑士', '蒼炎の剣士', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1600, '①：1回合1次，自己·对方的战斗阶段，以这张卡以外的自己场上1只战士族怪兽为对象才能发动。这张卡的攻击力下降600，作为对象的怪兽的攻击力上升600。 ②：场上的这张卡被对方破坏送去墓地时，把墓地的这张卡除外，以自己墓地1只战士族·炎属性怪兽为对象才能发动。那只战士族·炎属性怪兽特殊召唤。'),
(20871001, 'Blue Medicine', '蓝色药剂', 'ブルー・ポーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己回复400基本分。'),
(54582424, 'Blue Mountain Butterspy', '幻蝶刺客 英雄翠凤蝶', '幻蝶の刺客オオルリ', 'Effect Monster', 'Warrior', 'DARK', 4, NULL, 1700, '这张卡不能通常召唤。自己对战士族怪兽的召唤成功时，这张卡可以从手卡特殊召唤。这张卡不能作为同调素材。'),
(98884569, 'Blue Rose Dragon', '蓝蔷薇龙', 'ブルーローズ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1600, 1200, '①：场上的这张卡被破坏送去墓地时，以自己墓地1只「黑蔷薇龙」或者植物族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(14089428, 'Blue Thunder T-45', '蓝色雷电T45', 'ブルーサンダーT４５', 'Effect Monster', 'Machine', 'LIGHT', 4, 1700, 1000, '这张卡战斗破坏对方怪兽的场合，在自己场上把1只「雷电子机衍生物」（机械族·光·4星·攻/守1500）特殊召唤。这衍生物不能为上级召唤而解放。'),
(7953868, 'Blue-Blooded Oni', '苍血鬼', '蒼血鬼', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, 1700, '这张卡召唤·反转召唤成功时，变成守备表示。1回合1次，可以把自己场上存在的1个超量素材取除，选择自己墓地存在的1只4星的不死族怪兽特殊召唤。'),
(35282433, 'Blue-Eyed Silver Zombie', '青色眼银僵尸', '青眼の銀ゾンビ', 'Normal Monster', 'Zombie', 'DARK', 3, 900, 700, '据说可以从眼睛里射出怪异的光线，据说能让对方变成僵尸。'),
(64202399, 'Blue-Eyes Abyss Dragon', '深渊之青眼龙', '深淵の青眼龍', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2500, 2500, '这个卡名的①②③的效果1回合各能使用1次，若非自己的场上或墓地有「青眼白龙」存在的场合则不能发动。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张仪式魔法卡或「融合」加入手卡。 ②：自己结束阶段才能发动。从卡组把1只8星以上的龙族怪兽加入手卡。 ③：把墓地的这张卡除外才能发动。自己场上的全部8星以上的龙族怪兽的攻击力上升1000。'),
(43228023, 'Blue-Eyes Alternative Ultimate Dragon', '青眼究极亚龙', '青眼の究極亜竜', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 4500, 3800, '「青眼白龙」＋「青眼白龙」＋「青眼白龙」 ①：场上的这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ②：1回合1次，以对方场上1张卡为对象才能发动。那张卡破坏。已用原本卡名是「青眼亚白龙」的怪兽为素材让这张卡融合召唤的场合，这个效果的对象可以变成2张或者3张。这个效果发动的回合，这张卡不能攻击。'),
(38517737, 'Blue-Eyes Alternative White Dragon', '青眼亚白龙', '青眼の亜白龍', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '这张卡不能通常召唤。把手卡1只「青眼白龙」给对方观看的场合可以特殊召唤。这个方法的「青眼亚白龙」的特殊召唤1回合只能有1次。 ①：这张卡的卡名只要在场上·墓地存在当作「青眼白龙」使用。 ②：1回合1次，以对方场上1只怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那只怪兽破坏。'),
(20654247, 'Blue-Eyes Chaos Dragon', '青眼混沌龙', '青眼の混沌龍', 'Ritual Effect Monster', 'Dragon', 'DARK', 8, 3000, NULL, '「混沌形态」降临 这张卡不用仪式召唤不能特殊召唤。 ①：场上的这张卡不会被对方的效果破坏，对方不能把场上的这张卡作为效果的对象。 ②：使用「青眼白龙」作仪式召唤的这张卡的攻击宣言时才能发动。对方场上的全部怪兽的表示形式变更。这个效果让表示形式变更的怪兽的攻击力·守备力变成0。这个回合，这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(55410871, 'Blue-Eyes Chaos MAX Dragon', '青眼混沌极限龙', 'ブルーアイズ・カオス・MAX・ドラゴン', 'Ritual Effect Monster', 'Dragon', 'DARK', 8, 4000, NULL, '「混沌形态」降临 这张卡不用仪式召唤不能特殊召唤。 ①：只要这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的2倍数值的战斗伤害。'),
(30576089, 'Blue-Eyes Jet Dragon', '青眼喷气龙', 'ブルーアイズ・ジェット・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, NULL, '这个卡名的①③的效果1回合各能使用1次，若非自己的场上或墓地有「青眼白龙」存在的场合则不能发动。 ①：这张卡在手卡·墓地存在，场上的卡被战斗·效果破坏的场合才能发动。这张卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的其他卡不会被对方的效果破坏。 ③：这张卡进行战斗的伤害步骤开始时，以对方场上1张卡为对象才能发动。那张卡回到手卡。'),
(53347303, 'Blue-Eyes Shining Dragon', '青眼光龙', '青眼の光龍', 'Effect Monster', 'Dragon', 'LIGHT', 10, 3000, 2500, '这张卡不能通常召唤。把自己场上1只「青眼究极龙」解放的场合才能特殊召唤。 ①：这张卡的攻击力上升自己墓地的龙族怪兽数量×300。 ②：这张卡为对象的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。'),
(57043986, 'Blue-Eyes Solid Dragon', '青眼立体龙', 'ブルーアイズ・ソリッド・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果无效。 ②：对方把魔法·陷阱·怪兽的效果发动时才能发动。场上的这张卡回到持有者卡组，从卡组把1只「青眼白龙」特殊召唤。'),
(59822133, 'Blue-Eyes Spirit Dragon', '青眼精灵龙', '青眼の精霊龍', 'Synchro Monster', 'Dragon', 'LIGHT', 9, 2500, 3000, '调整＋调整以外的「青眼」怪兽1只以上 ①：只要这张卡在怪兽区域存在，双方不能把2只以上的怪兽同时特殊召唤。 ②：1回合1次，墓地的卡的效果发动时才能发动。那个发动无效。 ③：自己·对方回合，把同调召唤的这张卡解放才能发动。从额外卡组把「青眼精灵龙」以外的1只龙族·光属性同调怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(53183600, 'Blue-Eyes Toon Dragon', '青眼卡通龙', 'ブルーアイズ・トゥーン・ドラゴン', 'Toon Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '这张卡不能通常召唤。自己场上有「卡通世界」存在的状态，把自己场上2只怪兽解放的场合可以特殊召唤。 ①：这张卡在特殊召唤的回合不能攻击。 ②：这张卡的攻击宣言之际，自己必须支付500基本分。 ③：这张卡在对方场上没有卡通怪兽存在的场合，可以直接攻击。存在的场合，只能选择卡通怪兽作为攻击对象。 ④：场上的「卡通世界」被破坏时这张卡破坏。'),
(2129638, 'Blue-Eyes Twin Burst Dragon', '青眼双爆裂龙', '青眼の双爆裂龍', 'Fusion Monster', 'Dragon', 'LIGHT', 10, 3000, 2500, '「青眼白龙」＋「青眼白龙」 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己的怪兽区域的上记的卡送去墓地的场合可以从额外卡组特殊召唤。 ①：这张卡不会被战斗破坏。 ②：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡的攻击没让对方怪兽被破坏的伤害步骤结束时才能发动。那只对方怪兽除外。'),
(11443677, 'Blue-Eyes Tyrant Dragon', '青眼暴君龙', 'ブルーアイズ・タイラント・ドラゴン', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 3400, 2900, '「青眼白龙」＋龙族怪兽 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把有融合怪兽装备的1只自己的「青眼白龙」解放的场合可以特殊召唤。 ①：场上的这张卡不受陷阱卡的效果影响。 ②：这张卡可以向对方怪兽全部各作1次攻击。 ③：1回合1次，这张卡进行战斗的伤害步骤结束时，以自己墓地1张陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(23995346, 'Blue-Eyes Ultimate Dragon', '青眼究极龙', '青眼の究極竜', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 4500, 3800, '「青眼白龙」＋「青眼白龙」＋「青眼白龙」'),
(89604813, 'Blue-Eyes Ultimate Spirit Dragon', '青眼究极灵龙', '青眼の究極霊竜', 'Synchro Monster', 'Dragon', 'LIGHT', 12, 3500, 4000, '调整2只以上＋调整以外的「青眼」怪兽1只 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能把自己墓地的卡除外。 ②：卡的效果在场上发动时才能发动。那个发动无效，这张卡的攻击力直到回合结束时上升1000。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己墓地把「青眼究极灵龙」以外的1只龙族·光属性怪兽特殊召唤。'),
(89631139, 'Blue-Eyes White Dragon', '青眼白龙', '青眼の白龍', 'Normal Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '以高攻击力著称的传说之龙。任何对手都能粉碎，其破坏力不可估量。'),
(41396436, 'Blue-Winged Crown', '苍翼羽冠', '冠を戴く蒼き翼', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1600, 1200, '青白色的火鸟，头上的毛有如皇冠。'),
(55349375, 'Bluebeard, the Plunder Patroll Shipwright', '海造贼-蓝胡子海技士', '海造賊－青髭の海技士', 'Effect Monster', 'Fiend', 'WATER', 4, 500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「海造贼-蓝胡子海技士」以外的「海造贼」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡·怪兽区域送去墓地的场合，丢弃1张手卡才能发动。自己从卡组抽1张。'),
(22346472, 'Blustering Winds', '破天荒之风', '破天荒な風', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。选择的怪兽的攻击力·守备力直到下次的自己的准备阶段时上升1000。'),
(40634253, 'BM-4 Blast Spider', 'BM-4炸弹蜘蛛', 'BM－４ボムスパイダー', 'Effect Monster', 'Machine', 'DARK', 4, 1400, 2200, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以自己场上1只机械族·暗属性怪兽和对方场上1张表侧表示的卡为对象才能发动。那些卡破坏。 ②：自己场上的原本的种族·属性是机械族·暗属性的怪兽用战斗或者自身的效果破坏对方场上的怪兽送去墓地的场合才能发动。给与对方那1只破坏送去墓地的怪兽的原本攻击力一半数值的伤害。'),
(21340051, 'Boar Soldier', '野猪士兵', 'ボアソルジャー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 2000, 500, '被召唤的场合，这张卡破坏。对方控制着即使只有1只怪兽的场合，攻击力下降1000。'),
(8715625, 'Bokoichi the Freightening Car', '魔货物车辆 博科伊奇', '魔貨物車両 ボコイチ', 'Normal Monster', 'Machine', 'DARK', 2, 500, 500, '迪科伊奇专用的货物车辆。可以运载任何东西。但是到达目的地时大部分货物都会损坏。'),
(12146024, 'Bolt Escargot', '电击蜗牛', 'ボルト・エスカルゴ', 'Normal Monster', 'Thunder', 'WATER', 5, 1400, 1500, '吐出粘液然后用电击对方。'),
(48531733, 'Bolt Penguin', '电击企鹅', 'ボルト・ペンギン', 'Normal Monster', 'Thunder', 'WATER', 3, 1100, 800, '用双臂的电击鞭麻痹对手，勒脖子进行攻击。'),
(57409948, 'Bombardment Beetle', '爆弹椿象', '爆弾かめ虫', 'Flip Effect Monster', 'Insect', 'WIND', 2, 400, 900, '反转：确认对方场上的1张里侧守备表示的怪兽卡。如果被确认的怪兽是效果怪兽的话破坏，（反转效果不会发动），其他情况被确认卡变回原来的情况。'),
(71750854, 'Bomber Place', '炸弹数独', 'ボンバー・プレイス', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1350, 2400, '①：自己·对方回合，可以支付600基本分，从以下选择1个发动（同一连锁上最多1次）。 ●自己场上有1～6星的怪兽全部存在的场合才能发动。选对方场上1只表侧表示怪兽，等级·阶级·连接的数值和那个等级相同的除选的怪兽以外的对方场上的怪兽全部破坏。 ●选自己场上1只表侧表示怪兽，等级·阶级·连接的数值和那个等级相同的位于选的怪兽的正对面的对方怪兽全部破坏。'),
(60709218, 'Bond Between Teacher and Student', '师徒的牵绊', '師弟の絆', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「黑魔术师」存在的场合才能发动。从自己的手卡·卡组·墓地选1只「黑魔术少女」特殊召唤。那之后，可以从卡组选「黑·魔·导」「黑·魔·导·爆·裂·破」「黑·爆·裂·破·魔·导」「黑·魔·导·连·弹」的其中1张在自己的魔法与陷阱区域盖放。'),
(79402185, 'Bonding - D2O', '结合术-D2O', 'ボンディング－D２O', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把自己的手卡·场上2只「氘素龙」和1只「氧素龙」解放才能发动。从自己的手卡·卡组·墓地选1只「水龙」或者「水龙-团簇」当作「结合术-H2O」的效果特殊召唤。 ②：这张卡在墓地存在，「水龙」或者「水龙-团簇」从场上送去自己墓地的场合发动。墓地的这张卡回到手卡。'),
(6890729, 'Bonding - DHO', '结合术-DHO', 'ボンディング－DHO', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·墓地让「氘素龙」「氢素龙」「氧素龙」各1只回到卡组才能发动。从自己的手卡·墓地选1只「水龙-团簇」特殊召唤。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地选1只「水龙」或者「水龙-团簇」加入手卡。'),
(45898858, 'Bonding - H2O', '结合术-H2O', 'ボンディング－H２O', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上2只「氢素龙」和1只「氧素龙」解放才能发动。从自己的手卡·卡组·墓地把1只「水龙」特殊召唤。'),
(25784595, 'Bone Archfiend', '骸骨恶魔', 'ボーン・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，从自己的手卡·场上把这张卡以外的1张卡送去墓地才能发动。这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是龙族·暗属性同调怪兽不能从额外卡组特殊召唤。 ②：以自己场上1只表侧表示怪兽为对象才能发动。从手卡·卡组把1只恶魔族调整送去墓地，作为对象的怪兽的等级上升或下降1星。'),
(37675138, 'Bone Crusher', '白骨粉碎者', 'ボーンクラッシャー', 'Effect Monster', 'Zombie', 'EARTH', 4, 1600, 200, '这张卡被不死族怪兽的效果从自己墓地特殊召唤时，可以把对方场上存在的1张魔法·陷阱卡破坏。这张卡在特殊召唤的回合的结束阶段时破坏。'),
(21239280, 'Bone Mouse', '骨鼠', '骨ネズミ', 'Normal Monster', 'Zombie', 'DARK', 1, 400, 300, '被猫杀死的老鼠。为了报仇雪恨化为不死形态。'),
(47778083, 'Bone Temple Block', '骨木鱼', 'ボーン・テンプル・ブロック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。双方从对方墓地选择1只4星以下的怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段时破坏。'),
(98456117, 'Boneheimer', '骨海马', 'ボーンハイマー', 'Normal Monster', 'Aqua', 'WATER', 3, 850, 400, '在海中彷徨着，发现猎物后会将其水分吸干。'),
(85106525, 'Bonfire', '篝火', '篝火', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只4星以下的炎族怪兽加入手卡。'),
(59834564, 'Bonfire Colossus', '吓灼之魔神', '嚇灼の魔神', 'Effect Monster', 'Beast-Warrior', 'FIRE', 8, 2600, 2200, '①：自己场上有炎属性怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡特殊召唤的场合，以自己场上2只炎属性怪兽为对象发动。那些自己的炎属性怪兽破坏。'),
(263926, 'Bonze Alone', '独法师', '独法師', 'Effect Monster', 'Fairy', 'EARTH', 1, 100, 100, '自己场上有怪兽存在的场合，这张卡不能召唤·特殊召唤。 ①：这张卡可以从手卡攻击表示特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的怪兽召唤·反转召唤·特殊召唤的场合发动。这张卡破坏。');